package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*; public final class CoordinateGraphSvgRenderer { public String render(CoordinateGraphDiagramSpecV1 s){return render(s,Map.of());} public String render(CoordinateGraphDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),cx=s.viewport().width()/2,cy=s.viewport().height()/2;var b=new StringBuilder();b.append("<line x1=\"").append(p).append("\" y1=\"").append(cy).append("\" x2=\"").append(s.viewport().width()-p).append("\" y2=\"").append(cy).append("\" stroke=\"#000000\"/>");b.append("<line x1=\"").append(cx).append("\" y1=\"").append(p).append("\" x2=\"").append(cx).append("\" y2=\"").append(s.viewport().height()-p).append("\" stroke=\"#000000\"/>");for(var line:s.lines())b.append("<line x1=\"").append(cx-30).append("\" y1=\"").append(cy+30).append("\" x2=\"").append(cx+30).append("\" y2=\"").append(cy-30).append("\" stroke=\"#000000\"/>");for(var f:s.functions()){var value=values.get(f.coefficientKey());if(value==null)continue;if(f.functionKind()==CoordinateFunctionKind.INVERSE_PROPORTION)b.append("<path d=\"M ").append(p).append(" ").append(cy-1).append(" M ").append(cx+1).append(" ").append(cy-p).append("\" fill=\"none\" stroke=\"#000000\"/>");else b.append("<line x1=\"").append(p).append("\" y1=\"").append(cy-20).append("\" x2=\"").append(s.viewport().width()-p).append("\" y2=\"").append(cy+20).append("\" stroke=\"#000000\"/>");}return b.toString();} }
